import { Icon, IconProps } from '@adobe-commerce/elsie/components/Icon';
import * as Icons from '@adobe-commerce/elsie/icons';
import { Cart } from '@adobe-commerce/elsie/icons';
import type { Meta, StoryObj } from '@storybook/preact-vite';

/**
 * Use Icons as symbols or metaphors to communicate and enhance the user experience.
 * 
 * The Icon component supports three source types:
 * - Direct component imports
 * - Icon names from the built-in icon set
 * - SVGs from URLs (supports URLs that match the host domain)
 */
const meta: Meta<StoryIconProps> = {
  title: 'Components/Icon',
  component: Icon,
  argTypes: {
    source: {
      options: Object.keys(Icons),
      mapping: Icons,
      control: {
        type: 'select',
      },
      description: 'Select a built-in icon',
    },
    url: {
      control: {
        type: 'text',
      },
      description: 'Or enter a URL to an external SVG (this takes priority over icon selection)',
    },
    size: {
      control: 'select',
      options: ['12', '16', '24', '32', '64', '80'],
    },
    stroke: {
      control: 'select',
      options: ['1', '2', '3', '4'],
      description: 'Stroke width. Works only for stroke-based icons.',
    },
    title: {
      control: 'text',
      description: 'Title for the icon',
    },
  },
};

export default meta;

type Story = StoryObj<StoryIconProps>;

interface StoryIconProps extends IconProps {
  url?: string;
}

/**
 * ```ts
 * import { Icon } from '@adobe-commerce/elsie/components/Icon';
 * ```
 */

export const Primary: Story = {
  render: ({ url, source, ...args }: StoryIconProps) => {
    const iconSource = url || source;
    return <Icon {...args} source={iconSource as any} />;
  },
  args: {
    source: Cart,
  },
};

export const Lazy: Story = {
  render: ({ url, source, ...args }: StoryIconProps) => {
    const iconSource = url || source;
    return <Icon {...args} source={iconSource as any} />;
  },
  args: {
    source: 'Cart',
  },
};

export const AllBuiltInIcons: Story = {
  argTypes: {
    style: Object,
    url: {
      table: {
        disable: true
      }
    },
    source: {
      table: {
        disable: true
      }
    },
    title: {
      table: {
        disable: true
      }
    }
  },
  args: {
    style: {
      color: 'blue'
    }
  },
  render: (props) => (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(4, 1fr)',
        gap: '1rem',
      }}
    >
      {Object.keys(Icons).map((icon) => (
        // eslint-disable-next-line
        <>
          <span key={icon}>{icon}</span>
          {/* @ts-ignore */}
          <Icon {...props} source={Icons[icon]} />
        </>
      ))}
    </div>
  ),
};


